        string cardToken, double amountDouble)
    {
        // Arrange
        var amount = (decimal)amountDouble;

        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsNotImplementedException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync("tok_valid", 0m));
    }

    [TestMethod]
    [DataRow(-1.00, DisplayName = "Small negative amount")]
    [DataRow(-999.99, DisplayName = "Large negative amount")]
    public async Task ChargeAsync_NegativeAmount_ThrowsNotImplementedException(double amountDouble)
    {
        // Arrange
        var amount = (decimal)amountDouble;

        // Act & Assert
