    [TestMethod]
    public async Task ChargeAsync_NullCardToken_ThrowsNotImplementedException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(null!, 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyCardToken_ThrowsNotImplementedException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync(string.Empty, 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceCardToken_ThrowsNotImplementedException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.ChargeAsync("   ", 25.00m));
    }

    // ── RefundAsync ──────────────────────────────────────────────────

    [TestMethod]
    [DataRow("ch_valid_123", DisplayName = "Typical charge ID")]
    [DataRow("ch_abc_def_456", DisplayName = "Charge ID with underscores")]
    [DataRow("x", DisplayName = "Single-character charge ID")]
    public async Task RefundAsync_ValidChargeId_ThrowsNotImplementedException(string chargeId)
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.RefundAsync(chargeId));
    }

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsNotImplementedException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsNotImplementedException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.RefundAsync(string.Empty));
    }

    [TestMethod]
    public async Task RefundAsync_WhitespaceChargeId_ThrowsNotImplementedException()
    {
        // Act & Assert
        await Assert.ThrowsExactlyAsync<NotImplementedException>(
            () => _sut.RefundAsync("   "));
    }

    // ── Record type verification ─────────────────────────────────────

    [TestMethod]
    public void ChargeResult_Constructor_SetsProperties()
    {
        // Arrange & Act
        var result = new ChargeResult("ch_123", true);

        // Assert
        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void ChargeResult_FailedCharge_SetsSuccessFalse()
    {
        // Arrange & Act
        var result = new ChargeResult("ch_fail", false);

        // Assert
        Assert.AreEqual("ch_fail", result.ChargeId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void RefundResult_Constructor_SetsProperties()
    {
        // Arrange & Act
        var result = new RefundResult("rf_456", true);

        // Assert
        Assert.AreEqual("rf_456", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void RefundResult_FailedRefund_SetsSuccessFalse()
    {
        // Arrange & Act
        var result = new RefundResult("rf_fail", false);

        // Assert
        Assert.AreEqual("rf_fail", result.RefundId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void ChargeResult_Equality_SameValues_AreEqual()
    {
        // Arrange
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_1", true);

        // Assert
        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void ChargeResult_Equality_DifferentValues_AreNotEqual()
    {
        // Arrange
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_2", true);

        // Assert
        Assert.AreNotEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_Equality_SameValues_AreEqual()
    {
        // Arrange
        var a = new RefundResult("rf_1", true);
        var b = new RefundResult("rf_1", true);

        // Assert
        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_Equality_DifferentSuccessFlag_AreNotEqual()
    {
        // Arrange
        var a = new RefundResult("rf_1", true);
        var b = new RefundResult("rf_1", false);

        // Assert
        Assert.AreNotEqual(a, b);
    }
}

